<template>
  <Teleport to="body">
	<div v-if="show" ref="scrollEl" class="player" :class="[isDark ? 'player--dark' : 'player--light', `player--${storyDocument.settings.density}`, screenEffectClass, persistentEffectClasses, { 'player--performance-edit': performanceEditMode }]" :style="playerStyle" @click="advanceFromCanvas" @scroll.passive="schedulePlayerStickyAvatar">
      <header @click.stop>
        <button @click="started ? stopPlayback() : $emit('close')">← 返回</button>
        <div class="player-title">
          <input v-if="performanceEditMode" v-model="titleDraft" maxlength="120" aria-label="故事名" @change="saveTitle" @keydown.enter.prevent="saveTitle" />
          <strong v-else>{{ storyDocument.title }}</strong>
          <small v-if="performanceEditMode">演出编辑 · 点击消息设置编排</small>
          <small v-else-if="recording">录制中 · 点击画布推进</small>
          <small v-else>{{ started ? `${visibleCount} / ${playbackMessages.length}` : `${playbackMessages.length} 条消息` }}</small>
        </div>
        <div class="player-header-actions">
          <button v-if="!started" :class="{ active: performanceEditMode }" @click="togglePerformanceEdit">演出编辑</button>
          <button v-if="!started && performanceEditMode" :class="{ active: performanceToolsOpen }" @click="performanceToolsOpen=!performanceToolsOpen">编排工具</button>
          <button v-if="!started" title="打开故事语言源码编辑" @click="$emit('raw')">源码</button>
          <button v-if="!started" class="record" @click="startRecording">录制演出</button>
          <button class="primary" @click="headerAction">{{ finished ? '重新演出' : !started ? '开始演出' : paused ? '继续演出' : '暂停演出' }}</button>
          <button v-if="started" class="danger-solid" @click="recording ? finishRecording() : stopPlayback()">{{ recording ? '结束录制' : '关闭演出' }}</button>
        </div>
	  </header>
	  <section v-if="performanceEditMode && performanceToolsOpen" class="performance-tools" @click.stop>
		<nav><button :class="{active:performanceTool==='single'}" @click="performanceTool='single'">单条编辑</button><button :class="{active:performanceTool==='preview'}" @click="performanceTool='preview'">效果预览</button><button :class="{active:performanceTool==='brush'}" @click="performanceTool='brush'">特效笔刷</button><button :class="{active:performanceTool==='erase-one'}" @click="performanceTool='erase-one'">单条橡皮</button><button :class="{active:performanceTool==='multi'}" @click="performanceTool='multi'">多选批量</button><button :class="{active:performanceTool==='range'}" @click="performanceTool='range'">持续区间</button><button :class="{active:performanceTool==='erase-range'}" @click="performanceTool='erase-range'">区间橡皮</button></nav>
		<div v-if="performanceTool==='single'" class="tool-help">点击任一消息，设置该条的流式、文字动画、单次屏幕效果和停留时间。</div>
		<div v-else-if="performanceTool==='preview'" class="tool-help">点击任一消息，只预览该条的文字与屏幕效果，不会修改编排。</div>
		<div v-else-if="performanceTool==='brush'" class="brush-performance-tools"><n-select v-model:value="brushEffect" :options="effectBrushOptions" /><span>选择后点击消息直接涂上特效</span></div>
		<div v-else-if="performanceTool==='erase-one'" class="tool-help">点击消息清除该条的文字动画与单次屏幕效果；不会删除流式节奏或停留时间。</div>
		<div v-else-if="performanceTool==='multi'" class="batch-performance-tools"><span>已选 {{ performanceSelection.size }} 条</span><n-select v-model:value="batchStreamMode" :options="batchStreamOptions" /><n-select v-model:value="batchTokenAnimation" :options="batchTokenAnimationOptions" /><n-select v-model:value="batchScreenEffect" :options="batchScreenEffectOptions" /><button :disabled="!performanceSelection.size" class="primary" @click="applyBatchPerformance">应用</button><button @click="performanceSelection.clear()">清空</button></div>
		<div v-else-if="performanceTool==='range'" class="range-performance-tools"><n-select v-model:value="rangeEffect" :options="persistentEffectOptions" /><span>{{ rangeStartId ? '已选起点，再点结束消息' : '依次点击起点和结束消息' }}</span><button v-if="rangeStartId" @click="rangeStartId=''">取消起点</button><div v-if="storyDocument.effectTracks.length" class="effect-track-list"><button v-for="track in storyDocument.effectTracks" :key="track.id" :title="'删除 '+persistentEffectLabel(track.effect)" @click="removeEffectTrack(track.id)"><i :class="`effect-color--${track.effect}`"></i>{{ persistentEffectLabel(track.effect) }} ×</button></div></div>
		<div v-else class="tool-help">点击持续效果覆盖范围内的任一消息，删除经过该处的持续轨道。</div>
	  </section>
	  <div v-if="stickyCharacter" class="sticky-avatar" :style="stickyAvatarStyle"><span class="player-avatar" :style="{'--character-color':stickyCharacter.color}"><img v-if="avatar(stickyCharacter)" :src="avatar(stickyCharacter)" alt="" /><i v-else>{{ stickyCharacter.name.slice(0,1) }}</i></span></div>
	  <div v-if="interactionScene" :key="interactionScene.key" class="interaction-scene" :class="[`interaction-scene--${interactionScene.effect}`, { 'interaction-scene--reverse': interactionScene.reverse }]" aria-hidden="true">
		<span class="interaction-character interaction-character--source"><span class="player-avatar"><img v-if="avatar(interactionScene.source)" :src="avatar(interactionScene.source)" alt="" /><i v-else>{{ interactionScene.source.name.slice(0,1) }}</i></span></span>
		<span class="interaction-projectile">{{ interactionScene.emoji }}</span>
		<span class="interaction-character interaction-character--target"><span class="player-avatar"><img v-if="avatar(interactionScene.target)" :src="avatar(interactionScene.target)" alt="" /><i v-else>{{ interactionScene.target.name.slice(0,1) }}</i></span></span>
	  </div>
	  <Transition name="toast-pop"><div v-if="toastText" class="player-toast" role="status">{{ toastText }}</div></Transition>

      <main ref="playerMain" :style="canvasStyle">
		<div class="player-virtual-list" :style="{height:`${playerVirtualizer.getTotalSize()}px`}">
		<div v-for="{message,index,row} in virtualPlayerEntries" :key="String(row.key)" :ref="measurePlayerRow" class="player-virtual-row" :data-index="index" :style="{transform:`translateY(${row.start-playerScrollMargin}px)`}">
		  <article :data-id="message.id" class="player-message" :class="[`player-message--${character(message.characterId)?.position || 'left'}`, `player-message--group-${groupPosition(index)}`, screenEffectMessageId === message.id ? `player-message--effect-${screenEffectActive}` : '', { 'player-message--scripted': performanceEditMode && hasPerformance(message), 'player-message--tool-selected': performanceEditMode && performanceSelection.has(message.id), 'player-message--effect-active': screenEffectMessageId === message.id, 'player-message--revealed': started && index === visibleCount - 1 }]" :style="messageStyle(message)" @click.stop="onMessageClick(message)">
			<div v-if="performanceEditMode && effectRangesAt(message.id).length" class="effect-track-stack" aria-label="持续效果区间"><i v-for="range in effectRangesAt(message.id)" :key="range.track.id" :class="[`effect-color--${range.track.effect}`, `effect-track--${range.position}`]" :title="persistentEffectLabel(range.track.effect)"><b v-if="range.position==='start'||range.position==='single'">{{ persistentEffectLabel(range.track.effect) }}</b></i></div>
            <span v-if="avatarSlot(message.characterId)" class="player-avatar-slot" :class="{ 'player-avatar-slot--bottom': storyDocument.settings.avatarAlignment === 'bottom' }">
              <span v-if="showAvatar(message.characterId, index)" class="player-avatar"><img v-if="avatar(character(message.characterId))" :src="avatar(character(message.characterId))" alt="" /><i v-else>{{ character(message.characterId)?.name?.slice(0, 1) || '旁' }}</i></span>
            </span>
            <div class="player-message__content">
              <small v-if="showOutsideName(message.characterId, index) || storyDocument.settings.showTime">
                <template v-if="showOutsideName(message.characterId, index)"><span class="character-name" :style="nameStyle(character(message.characterId))">{{ character(message.characterId)?.name }}</span><span v-if="storyDocument.settings.showQqInPreview && character(message.characterId)?.imUserId" class="character-account"> · {{ character(message.characterId)?.imUserId }}</span></template>
                <span v-if="storyDocument.settings.showTime" class="message-time">{{ showOutsideName(message.characterId, index) ? ' · ' : '' }}{{ messageTime(message) }}</span>
              </small>
              <div class="bubble" :class="{ 'bubble--narrator-avatar': showNarratorBubbleAvatar(message.characterId, index) }">
				<button v-if="message.replyToId" class="reply-preview" type="button" @click.stop="scrollToVirtualMessage(message.replyToId)"><strong :style="nameStyle(replyCharacter(message.replyToId))">{{ replyCharacter(message.replyToId)?.name || '原消息' }}</strong><span>{{ replySummary(message.replyToId) }}</span></button>
                <div v-if="showNarratorBubbleAvatar(message.characterId, index)" class="narrator-identity"><span class="narrator-avatar"><img v-if="avatar(character(message.characterId))" :src="avatar(character(message.characterId))" alt="" /><i v-else>{{ character(message.characterId)?.name?.slice(0, 1) || '旁' }}</i></span><span v-if="showNarratorName(message.characterId, index)" class="narrator-identity__text"><span class="character-name" :style="nameStyle(character(message.characterId))">{{ character(message.characterId)?.name }}</span><span v-if="storyDocument.settings.showQqInPreview && character(message.characterId)?.imUserId" class="character-account"> · {{ character(message.characterId)?.imUserId }}</span></span></div>
				<img v-if="message.kind === 'image' && resourceAvailable(message.asset)" class="story-image" :src="imageUrl(message.asset)" :alt="message.alt || '图片'" @error="markResourceInvalid(message.asset)" @click.stop="openImage(message)" />
				<div v-else-if="message.kind === 'audio'" class="audio-content"><StoryAudioBubble v-if="resourceAvailable(message.asset)" :src="imageUrl(message.asset)" :duration-ms="message.durationMs" :seed="message.id" @error="markResourceInvalid(message.asset)" /><span v-else class="resource-placeholder">【语音】</span><p v-if="message.caption" class="audio-caption">{{ message.caption }}</p></div>
				<span v-else-if="message.kind === 'image'" class="resource-placeholder">【图片】</span>
                <span v-else-if="streamedMessageId === message.id" class="stream-output"><span v-for="token in streamedTokens" :key="token.key" class="stream-token" :class="`stream-token--${tokenAnimation(message)}`">{{ token.text }}</span><i v-if="storyDocument.settings.streamCursor !== 'none'" class="stream-cursor" :class="`stream-cursor--${storyDocument.settings.streamCursor}`"></i></span>
				<span v-else><template v-for="(segment,segmentIndex) in textSegments(renderedText(message))" :key="segmentIndex"><img v-if="segment.faceId" class="inline-cq-face" :src="`/api/editor/cq-face/${segment.faceId}`" :alt="`QQ 表情 ${segment.faceId}`" /><span v-else :class="{'inline-mention':segment.character}" :style="segment.character?nameStyle(segment.character):undefined">{{ segment.text }}</span></template></span>
              </div>
              <small v-if="performanceEditMode && hasPerformance(message)" class="performance-summary">{{ performanceSummary(message) }}</small>
            </div>
          </article>
		</div>
		</div>

        <article v-if="started && phase === 'typing' && typingCharacter" class="typing-indicator" :class="`typing-indicator--${storyDocument.settings.typingIndicatorEffect}`" :style="{'--character-color':typingCharacter.color}">
          <span class="player-avatar typing-indicator__avatar"><img v-if="avatar(typingCharacter)" :src="avatar(typingCharacter)" alt="" /><i v-else>{{ typingCharacter.name.slice(0, 1) }}</i></span>
          <span class="typing-indicator__bubble"><b>{{ typingCharacter.name }}</b><span>{{ storyDocument.settings.typingIndicatorText || '正在输入' }}</span><span class="typing-dots" aria-hidden="true"><i></i><i></i><i></i></span></span>
        </article>
      </main>

      <footer v-if="!started" @click.stop>
        <button :aria-expanded="performanceSettingsOpen" @click="togglePerformanceSettings">演出设置</button>
        <button :aria-expanded="displaySettingsOpen" @click="toggleDisplaySettings">界面设置</button>
        <button @click="imageExportOpen=true">导出长图</button>

        <Transition name="settings-pop"><section v-if="performanceSettingsOpen" class="settings-panel" aria-label="演出设置">
          <div class="settings-title"><div><strong>演出设置</strong><span>保存进 SSP 工程包</span></div><button aria-label="关闭演出设置" @click="performanceSettingsOpen=false">✕</button></div>
          <label class="switch-row"><span>自动播放</span><n-switch :value="storyDocument.settings.autoplay" @update:value="setSetting('autoplay', $event)" /></label>
          <label>计时方式<n-select :value="storyDocument.settings.playbackTiming" :options="timingOptions" @update:value="setSetting('playbackTiming', $event)" /></label>
          <label v-if="storyDocument.settings.playbackTiming === 'fixed'">默认间隔<n-input-number :value="storyDocument.settings.fixedDelayMs" :min="250" :max="30000" :step="250" :show-button="false" @update:value="setSetting('fixedDelayMs', $event ?? 2500)" /><span>ms</span></label>
          <label v-else>阅读速度<n-input-number :value="storyDocument.settings.chineseCharsPerMinute" :min="80" :max="1000" :step="20" :show-button="false" @update:value="setSetting('chineseCharsPerMinute', $event ?? 280)" /><span>字/分钟</span></label>
          <label class="switch-row"><span>流式输出</span><n-switch :value="storyDocument.settings.streamEnabled" @update:value="setSetting('streamEnabled', $event)" /></label>
          <DeferredSettingSlider v-if="storyDocument.settings.streamEnabled" label="输出速度" :value="storyDocument.settings.streamTokensPerSecond" :min="1" :max="30" unit=" 词/秒" @commit="setSetting('streamTokensPerSecond',$event)" />
          <DeferredSettingSlider v-if="storyDocument.settings.streamEnabled" label="速度随机量" :value="storyDocument.settings.streamSpeedJitterPercent" :min="0" :max="90" :step="5" unit="%" @commit="setSetting('streamSpeedJitterPercent',$event)" />
          <label v-if="storyDocument.settings.streamEnabled">词后停顿<n-input-number :value="storyDocument.settings.streamPauseMinMs" :min="0" :max="2000" :step="20" :show-button="false" @update:value="setSetting('streamPauseMinMs', Math.min($event ?? 0, storyDocument.settings.streamPauseMaxMs))" /><span>—</span><n-input-number :value="storyDocument.settings.streamPauseMaxMs" :min="0" :max="3000" :step="20" :show-button="false" @update:value="setSetting('streamPauseMaxMs', Math.max($event ?? 0, storyDocument.settings.streamPauseMinMs))" /><span>ms</span></label>
          <label v-if="storyDocument.settings.streamEnabled">字出现动画<n-select :value="storyDocument.settings.streamTokenAnimation" :options="tokenAnimationOptions" @update:value="setSetting('streamTokenAnimation', $event)" /></label>
          <label v-if="storyDocument.settings.streamEnabled">光标动画<n-select :value="storyDocument.settings.streamCursor" :options="cursorOptions" @update:value="setSetting('streamCursor', $event)" /></label>
          <label class="switch-row"><span>正在输入效果</span><n-switch :value="storyDocument.settings.typingIndicatorEnabled" @update:value="setSetting('typingIndicatorEnabled', $event)" /></label>
          <label v-if="storyDocument.settings.typingIndicatorEnabled">提示文本<n-input :value="storyDocument.settings.typingIndicatorText" maxlength="30" @update:value="setSetting('typingIndicatorText', $event)" /></label>
          <label v-if="storyDocument.settings.typingIndicatorEnabled">持续时间<n-input-number :value="storyDocument.settings.typingIndicatorMs" :min="0" :max="10000" :step="100" :show-button="false" @update:value="setSetting('typingIndicatorMs', $event ?? 700)" /><span>ms</span></label>
          <label v-if="storyDocument.settings.typingIndicatorEnabled">提示效果<n-select :value="storyDocument.settings.typingIndicatorEffect" :options="typingEffectOptions" @update:value="setSetting('typingIndicatorEffect', $event)" /></label>
        </section></Transition>

        <Transition name="settings-pop"><section v-if="displaySettingsOpen" class="settings-panel" aria-label="演出界面设置">
          <div class="settings-title"><div><strong>界面设置</strong><span>小图保持原始尺寸</span></div><button aria-label="关闭界面设置" @click="displaySettingsOpen=false">✕</button></div>
          <DeferredSettingSlider label="角色头像" :value="storyDocument.settings.avatarSize" :min="24" :max="96" :step="2" unit="px" @preview="previewDisplaySetting('avatarSize',$event)" @commit="commitDisplaySetting('avatarSize',$event)" />
          <DeferredSettingSlider label="旁白头像" :value="storyDocument.settings.narratorAvatarSize" :min="18" :max="72" :step="2" unit="px" @preview="previewDisplaySetting('narratorAvatarSize',$event)" @commit="commitDisplaySetting('narratorAvatarSize',$event)" />
          <DeferredSettingSlider label="字体" :value="storyDocument.settings.fontSize" :min="12" :max="32" unit="px" @preview="previewDisplaySetting('fontSize',$event)" @commit="commitDisplaySetting('fontSize',$event)" />
          <DeferredSettingSlider label="气泡上限" :value="storyDocument.settings.bubbleMaxWidth" :min="45" :max="95" unit="%" @preview="previewDisplaySetting('bubbleMaxWidth',$event)" @commit="commitDisplaySetting('bubbleMaxWidth',$event)" />
          <DeferredSettingSlider label="画布" :value="effectiveCanvasWidth" :min="canvasWidthMin" :max="canvasWidthMax" :step="20" unit="px" @preview="previewDisplaySetting('canvasWidth',$event)" @commit="commitDisplaySetting('canvasWidth',$event)" />
          <DeferredSettingSlider label="中线留白" :value="storyDocument.settings.centerGutterPercent" :min="0" :max="24" :step="2" unit="%" @preview="previewDisplaySetting('centerGutterPercent',$event)" @commit="commitDisplaySetting('centerGutterPercent',$event)" />
          <DeferredSettingSlider label="图片宽度上限" :value="storyDocument.settings.imageMaxWidthPercent" :min="20" :max="100" :step="5" unit="%" @preview="previewDisplaySetting('imageMaxWidthPercent',$event)" @commit="commitDisplaySetting('imageMaxWidthPercent',$event)" />
		  <DeferredSettingSlider label="图片高度上限" :value="storyDocument.settings.imageMaxHeightVh" :min="25" :max="90" :step="5" unit="vh" @preview="previewDisplaySetting('imageMaxHeightVh',$event)" @commit="commitDisplaySetting('imageMaxHeightVh',$event)" />
		  <label class="switch-row"><span>过滤场外发言</span><n-switch :value="storyDocument.settings.hideOffTopic" @update:value="setSetting('hideOffTopic', $event)" /></label>
		  <label class="switch-row"><span>组内头像跟随滚动</span><n-switch :value="storyDocument.settings.stickyGroupAvatar" @update:value="setSetting('stickyGroupAvatar', $event)" /></label>
        </section></Transition>
      </footer>

      <Teleport to="body"><Transition name="performance-pop"><div v-if="editingPerformanceMessage" class="performance-modal" @click.self="closePerformanceEditor"><form @submit.prevent="savePerformance">
        <header><strong>消息演出编排</strong><button type="button" @click="closePerformanceEditor">✕</button></header>
        <label>完整显示时长<n-input-number v-model:value="performanceForm.durationMs" clearable :min="0" :max="120000" :step="100" :show-button="false" placeholder="跟随默认" /><span>ms</span></label>
        <label v-if="editingPerformanceMessage.kind === 'text'" class="switch-row"><span>流式输出</span><n-switch v-model:value="performanceForm.streamEnabled" /></label>
        <label v-if="editingPerformanceMessage.kind === 'text'">字出现动画<n-select :value="performanceForm.tokenAnimation" :options="messageTokenAnimationOptions" @update:value="setPerformanceAnimation" /></label>
        <label>屏幕效果<n-select v-model:value="performanceForm.screenEffect" :options="screenEffectOptions" /></label>
        <label>角色互动<n-select :value="performanceForm.interactionEffect" :options="interactionEffectOptions" @update:value="setInteractionEffect" /></label>
        <template v-if="performanceForm.interactionEffect !== 'none'"><label>互动目标<n-select v-model:value="performanceForm.interactionTargetId" :options="interactionTargetOptions" /></label><label>符号 / Emoji<n-input v-model:value="performanceForm.interactionEmoji" maxlength="8" placeholder="使用该效果默认符号" /></label></template>
        <template v-if="editingPerformanceMessage.kind === 'image'"><label class="switch-row"><span>自动打开图片</span><n-switch v-model:value="performanceForm.imagePreviewEnabled" /></label><label v-if="performanceForm.imagePreviewEnabled">出现后打开<n-input-number v-model:value="performanceForm.imageOpenAfterMs" :min="0" :max="60000" :step="100" :show-button="false" /><span>ms</span></label><label v-if="performanceForm.imagePreviewEnabled">查看后关闭<n-input-number v-model:value="performanceForm.imageDurationMs" :min="250" :max="120000" :step="250" :show-button="false" /><span>ms</span></label></template>
        <template v-if="editingPerformanceMessage.kind === 'audio'"><label class="switch-row"><span>自动播放语音</span><n-switch v-model:value="performanceForm.audioPlaybackEnabled" /></label><label v-if="performanceForm.audioPlaybackEnabled">最长播放<n-input-number v-model:value="performanceForm.audioMaxDurationMs" :min="500" :max="300000" :step="500" :show-button="false" /><span>ms</span></label></template>
        <template v-if="editingPerformanceMessage.replyToId"><label class="switch-row"><span>定位引用消息</span><n-switch v-model:value="performanceForm.replyPreviewEnabled" /></label><label v-if="performanceForm.replyPreviewEnabled">查看后返回<n-input-number v-model:value="performanceForm.replyPreviewDurationMs" :min="500" :max="120000" :step="250" :show-button="false" /><span>ms</span></label></template>
        <section v-if="editingPerformanceMessage.kind === 'text'" class="token-timing">
		  <div><strong>逐词延迟偏移</strong><small>每个值都在全局智能延迟的基础上加减：正数更慢，负数更快，留空或 0 跟随全局。若自动分词不合适，可连续点选词块后合并；点一个自定义词组可拆分回智能分词。</small></div>
		  <div class="token-segmenter" aria-label="分词选择器"><div class="token-chip-list"><button v-for="token in performanceTokens" :key="`${token.start}-${token.end}`" type="button" :class="{selected:tokenSelected(token),custom:token.custom}" @click="selectToken(token.index)">{{ token.text.trim() || '空格' }}</button></div><div class="token-segment-actions"><span>{{ tokenSelectionText }}</span><button type="button" :disabled="tokenSelectionStart<0" @click="mergeSelectedTokens">合并选中</button><button type="button" :disabled="!selectedCustomToken" @click="splitSelectedToken">拆分词组</button><button type="button" :disabled="!performanceForm.tokenGroups.length" @click="resetTokenGroups">恢复智能分词</button></div></div>
		  <label v-for="token in performanceTokens" :key="token.index"><code :class="{custom:token.custom}">{{ token.text.trim() || '空格' }}</code><n-input-number :value="performanceForm.tokenDelays[token.index]" clearable :min="-30000" :max="30000" :step="25" :show-button="false" :placeholder="`默认约 ${defaultTokenDelay(token)} ms`" @update:value="setTokenDelay(token.index, $event)" /><span>ms</span></label>
		</section>
        <footer><button type="button" class="danger" @click="clearPerformance">清除编排</button><span></span><button type="button" @click="closePerformanceEditor">取消</button><button class="primary" type="submit">保存</button></footer>
      </form></div></Transition></Teleport>

      <Teleport to="body"><div v-if="imageExportOpen" class="performance-modal" @click.self="imageExportOpen=false"><form class="image-export-form" @submit.prevent="exportLongImages"><header><div><strong>导出预览长图</strong><small>按消息边界分页，不会截断气泡</small></div><button type="button" @click="imageExportOpen=false">✕</button></header><label>单张高度上限<n-input-number v-model:value="imageExportMaxHeight" :min="2000" :max="16000" :step="500" :show-button="false" /><span>px</span></label><p>一页时直接下载 PNG；超过限制时按顺序生成多张并打包 ZIP。</p><footer><span></span><span></span><button type="button" @click="imageExportOpen=false">取消</button><button class="primary" type="submit" :disabled="imageExporting">{{ imageExporting?'正在生成…':'开始导出' }}</button></footer></form></div></Teleport>

      <StoryImageViewer :show="imageViewerOpen" :src="imageViewerSrc" :alt="imageViewerAlt" :canvas-width="effectiveCanvasWidth" :auto-close-ms="imageViewerAutoCloseMs" @close="closeImageViewer" />
    </div>
  </Teleport>
</template>

<script setup lang="ts">
