function markResourceInvalid(asset: StoryAssetRef) { if (invalidResources.has(asset.id)) return; invalidResources.add(asset.id); alert(`${asset.mime.startsWith("audio/") ? "语音" : "图片"}链接已经失效，已改为占位显示。`); }
