function handleAvatarError(event: Event) { const image = event.target; if (!(image instanceof HTMLImageElement)) return; const match = image.src.match(/\/api\/editor\/avatar\/user\/([^?]+)/); if (match) invalidAvatars.add(decodeURIComponent(match[1])); }
