function updateStickyAvatar() { const player = scrollEl.value; if (!player || !storyDocument.value.settings.stickyGroupAvatar || !storyDocument.value.settings.showAvatars) { stickyCharacterId.value = ""; return; } const playerRect = player.getBoundingClientRect(); const headerBottom = player.querySelector<HTMLElement>(":scope > header")?.getBoundingClientRect().bottom || playerRect.top; const toolsBottom = player.querySelector<HTMLElement>(":scope > .performance-tools")?.getBoundingClientRect().bottom || headerBottom; const topMode = storyDocument.value.settings.avatarAlignment === "top"; const edge = topMode ? Math.max(playerRect.top,headerBottom,toolsBottom)+12 : playerRect.bottom-12; const articles=Array.from(player.querySelectorAll<HTMLElement>(".player-virtual-row .player-message[data-id]")); const article=(topMode?articles:[...articles].reverse()).find(node=>{const rect=node.getBoundingClientRect();return topMode?rect.bottom>edge:rect.top<edge}); if(!article){stickyCharacterId.value="";return} const row=article.closest<HTMLElement>(".player-virtual-row");const index=Number(row?.dataset.index);const message=visibleMessages.value[index];const item=message?character(message.characterId):undefined;const rect=article.getBoundingClientRect();const position=Number.isFinite(index)?groupPosition(index):"single";const groupContinues=topMode?["middle","last"].includes(position):["first","middle"].includes(position);const crossed=topMode?rect.top<edge:rect.bottom>edge;if(!item||item.isNarrator||item.position==="narrator"||(!crossed&&!groupContinues)){stickyCharacterId.value="";return}stickyCharacterId.value=item.id;const style:Record<string,string>={};if(topMode)style.top=`${edge}px`;else style.bottom=`${Math.max(12,innerHeight-edge)}px`;if(item.position==="right")style.right=`${Math.max(8,innerWidth-rect.right)}px`;else style.left=`${Math.max(8,rect.left)}px`;stickyAvatarStyle.value=style; }
