function messageTime(message: StoryMessage) { if (message.timeText) return message.timeText; if (!message.time) return "--:--"; const value = message.time > 10_000_000_000 ? message.time : message.time * 1000; return new Date(value).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }); }
